37	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
38	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
39	import org.springframework.samples.petclinic.rest.api.OwnersApi;
40	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
41	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
42	import org.springframework.samples.petclinic.rest.dto.PetDto;
43	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
44	import org.springframework.samples.petclinic.rest.dto.VisitDto;
45	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
46	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
47	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
48	import org.springframework.samples.petclinic.service.ClinicService;
49	import org.springframework.security.access.prepost.PreAuthorize;
50	import org.springframework.web.bind.annotation.CrossOrigin;
51	import org.springframework.web.bind.annotation.RequestMapping;
52	import org.springframework.web.bind.annotation.RestController;
53	import org.springframework.web.util.UriComponentsBuilder;
54	
55	import jakarta.transaction.Transactional;
56	
57	/**
58	 * @author Vitaliy Fedoriv
59	 */
60	
61	@RestController
62	@CrossOrigin(exposedHeaders = "errors, content-type")
63	@RequestMapping("/api")
64	public class OwnerRestControllerV1 implements OwnersApi {
65	
66	    private final ClinicService clinicService;
67	
68	    private final OwnerMapper ownerMapper;
69	
70	    private final PetMapper petMapper;
71	
72	    private final VisitMapper visitMapper;
73	
74	    private final TelephoneNormalizer telephoneNormalizer;
75	
76	    private final AddressNormalizer addressNormalizer;
77	
78	    public OwnerRestControllerV1(ClinicService clinicService,
79	                                 OwnerMapper ownerMapper,
80	                                 PetMapper petMapper,
81	                                 VisitMapper visitMapper,
82	                                 TelephoneNormalizer telephoneNormalizer,
83	                                 AddressNormalizer addressNormalizer) {
84	        this.clinicService = clinicService;
85	        this.ownerMapper = ownerMapper;
86	        this.petMapper = petMapper;
87	        this.visitMapper = visitMapper;
88	        this.telephoneNormalizer = telephoneNormalizer;
89	        this.addressNormalizer = addressNormalizer;
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
95	        Collection<Owner> owners;
96	        if (lastName != null) {
97	            owners = this.clinicService.findOwnerByLastName(lastName);
98	        } else {
99	            owners = this.clinicService.findAllOwners();
100	        }
101	        if (owners.isEmpty()) {
102	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
103	        }
104	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
105	    }
106	
107	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
108	    @Override
109	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
110	        Owner owner = this.clinicService.findOwnerById(ownerId);
111	        if (owner == null) {
112	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
113	        }
114	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
115	    }
116	
117	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
118	    @Override
119	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
120	        normalizeAndValidate(ownerFieldsDto);
121	        HttpHeaders headers = new HttpHeaders();
122	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
123	        owner.setCustomerCode(generateCustomerCode(owner.getLastName()));
124	        owner.setNamesakeCount(countNamesakes(owner));
125	        assignHousehold(owner, ownerFieldsDto);
126	        this.clinicService.saveOwner(owner);
127	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
128	        headers.setLocation(UriComponentsBuilder.newInstance()
129	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
130	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
131	    }
132	
133	    /**
134	     * Prepares a new owner's payload for persistence, applying every rule an incoming owner must satisfy before it is
135	     * saved. The address is first normalized to its canonical stored form and written back onto the payload; required
136	     * fields are then checked (so an address that is blank after normalization is rejected); the telephone is
137	     * normalized to its canonical stored form, written back onto the payload and rejected if another owner already uses
138	     * it; the email is canonicalized; and a missing registration date defaults to the current date. The payload is
139	     * mutated in place so the caller can map and save it directly.
140	     *
141	     * @param ownerFieldsDto the incoming owner payload, mutated in place
142	     * @throws MissingOwnerFieldsException if any required field is missing or blank
143	     * @throws DuplicateTelephoneException if another owner already uses the normalized telephone
144	     */
145	    private void normalizeAndValidate(OwnerFieldsDto ownerFieldsDto) {
146	        ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
147	        validateRequiredFields(ownerFieldsDto);
148	        String telephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
149	        ownerFieldsDto.setTelephone(telephone);
150	        requireUniqueTelephone(telephone);
151	        requireUniqueHousehold(ownerFieldsDto);
152	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
153	        if (ownerFieldsDto.getRegistrationDate() == null) {
154	            ownerFieldsDto.setRegistrationDate(LocalDate.now());
155	        }
156	    }
157	
158	    /**
159	     * Builds an owner's {@code customerCode}, formatted {@code <LAST3>-<NNNN>}. {@code LAST3} is the upper-cased first
160	     * three letters of the last name and {@code NNNN} is a global 4-digit zero-padded sequence equal to one more than
161	     * the current number of owners (e.g. {@code SMI-0007}).
162	     *
163	     * @param lastName the owner's last name
164	     * @return the generated customer code
165	     */
166	    private String generateCustomerCode(String lastName) {
167	        String prefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
168	        int sequence = this.clinicService.findAllOwners().size() + 1;
169	        return String.format("%s-%04d", prefix, sequence);
170	    }
171	
172	    /**
173	     * Counts how many existing owners already share the given owner's first and last name, compared
174	     * case-insensitively. Invoked before the new owner is saved, so the result reflects only owners that predate this
175	     * create; it is zero when the owner's name is unique.
176	     *
177	     * @param owner the newly mapped owner about to be saved
178	     * @return the number of existing owners sharing the same first and last name (case-insensitively)
179	     */
180	    private int countNamesakes(Owner owner) {
181	        String firstName = owner.getFirstName();
182	        String lastName = owner.getLastName();
183	        return (int) this.clinicService.findAllOwners().stream()
184	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
185	                && lastName.equalsIgnoreCase(existing.getLastName()))
186	            .count();
187	    }
188	
189	    /**
190	     * Rejects an owner payload that omits or leaves blank any required field. Bean Validation already rejects missing
191	     * ({@code null}) required fields, but permits values that are blank (empty or whitespace-only) for fields without a
192	     * stricter pattern, so this check enforces the "missing or blank" rule uniformly across every required field.
193	     *
194	     * @param ownerFieldsDto the owner payload to validate
195	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or telephone is missing or blank
196	     */
197	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
198	        List<String> missingFields = new ArrayList<>();
199	        requireText(missingFields, "firstName", ownerFieldsDto.getFirstName());
200	        requireText(missingFields, "lastName", ownerFieldsDto.getLastName());
201	        requireText(missingFields, "address", ownerFieldsDto.getAddress());
202	        requireText(missingFields, "city", ownerFieldsDto.getCity());
203	        requireText(missingFields, "telephone", ownerFieldsDto.getTelephone());
204	        if (!missingFields.isEmpty()) {
205	            throw new MissingOwnerFieldsException(missingFields);
206	        }
207	    }
208	
209	    private void requireText(List<String> missingFields, String fieldName, String value) {
210	        if (value == null || value.isBlank()) {
211	            missingFields.add(fieldName);
212	        }
213	    }
214	
215	    /**
216	     * Normalizes an optional owner email. A syntactically valid address is already enforced by Bean Validation on the
217	     * request payload, so this only canonicalizes the value that gets stored and returned by lower-casing it. A missing
218	     * (blank or {@code null}) email is left untouched, since the field is optional.
219	     *
220	     * @param email the raw email value from the request, may be {@code null}
221	     * @return the lower-cased email, or the original value when none was supplied
222	     */
223	    private String normalizeEmail(String email) {
224	        if (email == null || email.isBlank()) {
225	            return email;
226	        }
227	        return email.toLowerCase();
228	    }
229	
230	    /**
231	     * Rejects creating an owner whose normalized telephone is already used by another owner. Existing owners' stored
232	     * telephones are canonicalized the same way before comparison, so the rule holds regardless of how their number was
233	     * originally formatted.
234	     *
235	     * @param telephone the normalized telephone of the owner being created
236	     * @throws DuplicateTelephoneException if any existing owner already uses the same normalized telephone
237	     */
238	    private void requireUniqueTelephone(String telephone) {
239	        boolean inUse = this.clinicService.findAllOwners().stream()
240	            .map(existing -> telephoneNormalizer.canonicalize(existing.getTelephone()))
241	            .anyMatch(telephone::equals);
242	        if (inUse) {
243	            throw new DuplicateTelephoneException("telephone is already in use by another owner");
244	        }
245	    }
246	
247	    /**
248	     * Rejects creating an owner who shares a household (see {@link #findHouseholdMembers}) with an existing owner,
249	     * unless the request opts in by setting {@code sharesHousehold} to {@code true}.
250	     *
251	     * @param ownerFieldsDto the incoming owner payload
252	     * @throws DuplicateOwnerException if another owner already belongs to the same household and the request does not
253	     *                                 set {@code sharesHousehold}
254	     */
255	    private void requireUniqueHousehold(OwnerFieldsDto ownerFieldsDto) {
256	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
257	            return;
258	        }
259	        if (!findHouseholdMembers(ownerFieldsDto).isEmpty()) {
260	            throw new DuplicateOwnerException(
261	                "an owner with the same last name and address already exists in this household");
262	        }
263	    }
264	
265	    /**
266	     * Finds the existing owners that belong to the same household as the given payload, i.e. those sharing both its
267	     * last name and address. The last name is compared case-insensitively after collapsing runs of whitespace to a
268	     * single space and trimming; the address is compared in its normalized form (see {@link AddressNormalizer}), so
269	     * incidental formatting differences and abbreviation variants do not affect membership.
270	     *
271	     * @param ownerFieldsDto the incoming owner payload
272	     * @return the existing owners in the same household, in the order {@link ClinicService#findAllOwners()} returns
273	     *         them; empty when none match
274	     */
275	    private List<Owner> findHouseholdMembers(OwnerFieldsDto ownerFieldsDto) {
276	        String lastName = collapseWhitespace(ownerFieldsDto.getLastName());
277	        String address = addressNormalizer.normalize(ownerFieldsDto.getAddress());
278	        return this.clinicService.findAllOwners().stream()
279	            .filter(existing -> collapseWhitespace(existing.getLastName()).equalsIgnoreCase(lastName)
280	                && addressNormalizer.normalize(existing.getAddress()).equals(address))
281	            .toList();
282	    }
283	
284	    /**
285	     * Canonicalizes a value for household comparison by trimming it and collapsing every run of whitespace to a single
286	     * space. Case is deliberately preserved here; callers compare the result case-insensitively.
287	     *
288	     * @param value the raw field value, may be {@code null}
289	     * @return the whitespace-collapsed value, or an empty string when {@code null}
290	     */
291	    private String collapseWhitespace(String value) {
292	        if (value == null) {
293	            return "";
294	        }
295	        return value.strip().replaceAll("\\s+", " ");
296	    }
297	
298	    /**
299	     * Assigns the shared {@code householdId} for an owner joining an existing household. Only owners created with
300	     * {@code sharesHousehold} set to {@code true} that actually match an existing household (see
301	     * {@link #findHouseholdMembers}) are given an identifier; single owners keep a {@code null} household. The
302	     * identifier is derived deterministically from the household's last name and address, so every member of the same
303	     * household resolves to the same stable value regardless of creation order. Existing members that predate the
304	     * feature and still lack the identifier are backfilled so the whole household shares it.
305	     *
306	     * @param owner          the newly mapped owner about to be saved
307	     * @param ownerFieldsDto the incoming owner payload
308	     */
309	    private void assignHousehold(Owner owner, OwnerFieldsDto ownerFieldsDto) {
310	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
311	            return;
312	        }
313	        List<Owner> members = findHouseholdMembers(ownerFieldsDto);
314	        if (members.isEmpty()) {
315	            return;
316	        }
317	        String householdId = generateHouseholdId(ownerFieldsDto);
318	        owner.setHouseholdId(householdId);
319	        for (Owner member : members) {
320	            if (!householdId.equals(member.getHouseholdId())) {
321	                member.setHouseholdId(householdId);
322	                this.clinicService.saveOwner(member);
323	            }
324	        }
325	    }
326	
327	    /**
328	     * Derives a household's stable identifier, formatted {@code HH-<12 hex chars>}, from the case-insensitive,
329	     * whitespace-collapsed last name and the normalized address (see {@link AddressNormalizer}). Being a pure function
330	     * of those fields, it is identical for every owner in the same household and never changes over time.
331	     *
332	     * @param ownerFieldsDto the incoming owner payload
333	     * @return the household identifier
334	     */
335	    private String generateHouseholdId(OwnerFieldsDto ownerFieldsDto) {
336	        String key = collapseWhitespace(ownerFieldsDto.getLastName()).toLowerCase()
337	            + "\n" + addressNormalizer.normalize(ownerFieldsDto.getAddress()).toLowerCase();
338	        try {
339	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
340	            StringBuilder hex = new StringBuilder();
341	            for (int i = 0; i < 6; i++) {
342	                hex.append(String.format("%02X", digest[i]));
343	            }
344	            return "HH-" + hex;
345	        } catch (NoSuchAlgorithmException ex) {
346	            throw new IllegalStateException("SHA-256 is not available", ex);
347	        }
348	    }
349	
350	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
351	    @Override
352	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
353	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
354	        if (currentOwner == null) {
355	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
356	        }
357	        currentOwner.setAddress(ownerFieldsDto.getAddress());
358	        currentOwner.setCity(ownerFieldsDto.getCity());
359	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
360	        currentOwner.setLastName(ownerFieldsDto.getLastName());
361	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
362	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
363	        this.clinicService.saveOwner(currentOwner);
364	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
365	    }
366	
367	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
368	    @Transactional
369	    @Override
370	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
371	        Owner owner = this.clinicService.findOwnerById(ownerId);
372	        if (owner == null) {
373	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
374	        }
375	        this.clinicService.deleteOwner(owner);
376	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
377	    }
378	
379	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
380	    @Override
381	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
382	        Owner owner = this.clinicService.findOwnerById(ownerId);
383	        if (owner == null) {
384	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
385	        }
386	        HttpHeaders headers = new HttpHeaders();
387	        Pet pet = petMapper.toPet(petFieldsDto);
388	        owner.setId(ownerId);
389	        pet.setOwner(owner);
390	        pet.getType().setName(null);
391	        this.clinicService.savePet(pet);
392	        PetDto petDto = petMapper.toPetDto(pet);
393	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
394	            .buildAndExpand(pet.getId()).toUri());
395	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
396	    }
397	
398	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
399	    @Override
400	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
401	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
402	        if (currentOwner != null) {
403	            Pet currentPet = this.clinicService.findPetById(petId);
404	            if (currentPet != null) {
405	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
406	                currentPet.setName(petFieldsDto.getName());
407	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
408	                this.clinicService.savePet(currentPet);
409	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
410	            }
411	        }
412	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
413	    }
414	
415	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
416	    @Override
417	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
418	        HttpHeaders headers = new HttpHeaders();
419	        Visit visit = visitMapper.toVisit(visitFieldsDto);
420	        Pet pet = new Pet();
421	        pet.setId(petId);
422	        visit.setPet(pet);
423	        this.clinicService.saveVisit(visit);
424	        VisitDto visitDto = visitMapper.toVisitDto(visit);
425	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
426	            .buildAndExpand(visit.getId()).toUri());
427	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
428	    }
429	
430	
431	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
432	    @Override
433	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
434	        Owner owner = this.clinicService.findOwnerById(ownerId);
435	        if (owner != null) {
436	            Pet pet = owner.getPet(petId);
437	            if (pet != null) {
438	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
